// ============================================================
// WF6 — ROUTER
// Reads dispute_type and routes to correct handler branch.
//
// Supported dispute_type values:
//   'no_show'            → provider never arrived
//   'provider_cancelled' → provider cancelled after confirmation
//   'quality_complaint'  → bad work / auto-escalated from WF5
//   'price_disagreement' → customer charged more than quoted
//   'overrun'            → job took longer, extra charges disputed
// ============================================================
const body = $input.first().json.body || $input.first().json;

const validTypes = [
  'no_show',
  'provider_cancelled',
  'quality_complaint',
  'price_disagreement',
  'overrun'
];

const disputeType = body.dispute_type || 'quality_complaint';

if (!validTypes.includes(disputeType)) {
  return [{ json: {
    status: 'error',
    message: `Invalid dispute_type '${disputeType}'. Must be one of: ${validTypes.join(', ')}`,
    workflow: 'WF6-Router'
  }}];
}

if (!body.booking_id) {
  return [{ json: {
    status: 'error',
    message: 'booking_id is required',
    workflow: 'WF6-Router'
  }}];
}

console.log('=== WF6 Dispute Router ===');
console.log('Type:', disputeType);
console.log('Booking:', body.booking_id);
console.log('Auto-escalated from WF5:', body.auto_escalated || false);

return [{ json: { ...body, dispute_type: disputeType } }];

// ============================================================
// WF6 — NO SHOW HANDLER
// Provider never arrived at the booked time.
// Decision: full refund eligibility + provider penalty + reschedule offer.
// ============================================================
const data = $('WF6 — Router').first().json;
const now = new Date();

// Penalty logic: first offence = warning, repeat = suspension
const cancellationRate = parseFloat(data.provider_cancellation_rate) || 0.12;
const isRepeatOffender = cancellationRate > 0.20;

const penalty = isRepeatOffender
  ? 'SUSPENDED — Provider removed from active pool pending review'
  : 'WARNING — Strike added to provider record. 3 strikes = suspension.';

const resolution = {
  status: 'dispute_resolved',
  dispute_type: 'no_show',
  booking_id: data.booking_id,
  provider_name: data.provider_name,
  provider_id: data.provider_id,
  user_email: data.user_email,
  resolution: 'no_show_confirmed',
  decision: {
    refund: {
      eligible: true,
      amount_pkr: data.price_pkr || 0,
      method: 'Credit to next booking or cash refund',
      note: 'Full refund approved — provider did not show up'
    },
    provider_action: {
      penalty: penalty,
      cancellation_rate_updated: Math.min(1, cancellationRate + 0.10),
      blacklisted: isRepeatOffender,
      matching_impact: isRepeatOffender
        ? 'Provider BLACKLISTED — will not appear in future WF2 results'
        : 'Provider score penalized — lower priority in future matches'
    },
    reschedule_offer: {
      available: true,
      message: 'Kya aap doosre provider ke saath reschedule karna chahte hain?',
      action: 'POST to khadmat-booking with action: get_slots and new provider details'
    }
  },
  antigravity_trace: {
    reasoning: `No-show detected for booking ${data.booking_id}. Provider ${data.provider_name} did not arrive. Cancellation rate: ${(cancellationRate * 100).toFixed(0)}%. Decision: ${isRepeatOffender ? 'Blacklist + full refund' : 'Warning + full refund + reschedule offer'}.`,
    confidence: 95,
    escalate_to_human: isRepeatOffender
  },
  customer_message:
    `Humein afsos hai ke ${data.provider_name} nahi aaye.\n` +
    `Aapka PKR ${data.price_pkr || 0} refund process ho raha hai.\n` +
    `Hum aapko ek naya provider dhundh ke denge — koi extra charge nahi.`,
  simulated_whatsapp:
    `No-Show Alert — Khadmat AI\n` +
    `Booking: ${data.booking_id}\n` +
    `Provider ${data.provider_name} nahi pahunche.\n` +
    `Full refund approved: PKR ${data.price_pkr || 0}\n` +
    `Reschedule ke liye reply karein.`,
  workflow: 'WF6-NoShow',
  timestamp: now.toISOString()
};

console.log('=== WF6 No Show ===');
console.log('Blacklisted:', isRepeatOffender);
console.log('Refund:', data.price_pkr);

return [{ json: resolution }];

// ============================================================
// WF6 — PROVIDER CANCELLED HANDLER
// Provider cancelled after booking was confirmed.
// Auto-triggers rebooking using WF2 alternatives list.
// ============================================================
const data = $('WF6 — Router').first().json;
const now = new Date();

// Use alternatives passed in from WF2 response (if available)
const alternatives = data.alternatives || [];
const hasAlternatives = alternatives.length > 0;

// Pick best alternative (first in already-ranked list from WF2)
const nextBestProvider = hasAlternatives ? alternatives[0] : null;

// Hours until appointment
const bookingDate = new Date(data.booking_date || now);
const hoursUntilBooking = Math.round((bookingDate - now) / 3600000);
const isUrgent = hoursUntilBooking < 3;

const resolution = {
  status: 'dispute_in_progress',
  dispute_type: 'provider_cancelled',
  booking_id: data.booking_id,
  user_email: data.user_email,
  cancelled_provider: {
    id: data.provider_id,
    name: data.provider_name,
    penalty: 'Cancellation strike added. Rate updated in matching system.',
    cancellation_logged: true
  },
  rebooking: {
    triggered: hasAlternatives,
    urgency: isUrgent ? 'HIGH — less than 3 hours to appointment' : 'NORMAL',
    next_best_provider: nextBestProvider ? {
      name: nextBestProvider.name,
      score: nextBestProvider.computed_score,
      rating: nextBestProvider.rating,
      distance_km: nextBestProvider.distance_km,
      estimated_arrival: nextBestProvider.estimated_arrival
    } : null,
    auto_rebook_instruction: nextBestProvider
      ? `System will auto-book ${nextBestProvider.name} if customer approves.`
      : 'No alternatives available. Manual rebooking required.',
    rebook_payload: nextBestProvider ? {
      action: 'get_slots',
      provider_id: nextBestProvider.id,
      provider_name: nextBestProvider.name,
      service_type: data.service_type,
      location: data.location,
      booking_date: data.booking_date,
      price_pkr: data.price_pkr,
      availability_slots: nextBestProvider.availability_slots || ['09:00', '11:00', '14:00']
    } : null
  },
  compensation: {
    eligible: isUrgent,
    amount_pkr: isUrgent ? 200 : 0,
    note: isUrgent
      ? 'PKR 200 discount on next booking — urgent cancellation compensation'
      : 'No compensation — cancellation was more than 3 hours before appointment'
  },
  antigravity_trace: {
    reasoning: `Provider ${data.provider_name} cancelled booking ${data.booking_id}. Hours until appointment: ${hoursUntilBooking}h. Urgency: ${isUrgent ? 'HIGH' : 'NORMAL'}. Next best alternative: ${nextBestProvider?.name || 'None'}. Auto-rebooking: ${hasAlternatives ? 'triggered' : 'not possible'}.`,
    confidence: 90,
    escalate_to_human: !hasAlternatives && isUrgent
  },
  customer_message:
    `${data.provider_name} ne booking cancel kar di hai.\n` +
    (nextBestProvider
      ? `Hum ne aapke liye next best provider ${nextBestProvider.name} dhundh liya hai. Confirm karein?`
      : `Filhal koi alternative provider available nahi — hum aapko manually help karenge.`),
  simulated_whatsapp:
    `Provider Cancelled — Khadmat AI\n` +
    `Booking: ${data.booking_id}\n` +
    `${data.provider_name} ne cancel kar diya.\n` +
    (nextBestProvider
      ? `New provider available: ${nextBestProvider.name} (Score: ${nextBestProvider.computed_score})\nConfirm karein?`
      : `Koi alternative nahi mila. Team contact karegi.`),
  workflow: 'WF6-ProviderCancelled',
  timestamp: now.toISOString()
};

console.log('=== WF6 Provider Cancelled ===');
console.log('Has alternatives:', hasAlternatives);
console.log('Urgent:', isUrgent);
console.log('Next provider:', nextBestProvider?.name || 'None');

return [{ json: resolution }];

// ============================================================
// WF6 — QUALITY COMPLAINT HANDLER
// Triggered manually or auto-escalated from WF5 (rating <= 2).
// Classifies severity, decides compensation, flags provider.
// ============================================================
const data = $('WF6 — Router').first().json;
const now = new Date();

const rating = parseFloat(data.rating) || 1;
const sentiment = data.sentiment || 'negative';
const review = data.review || data.review_text || '';
const autoEscalated = data.auto_escalated || false;

// ── Severity Classification ───────────────────────────────
let severity, compensationPct, providerAction, escalateHuman;

if (rating === 1 || (sentiment === 'negative' && rating <= 2)) {
  severity = 'CRITICAL';
  compensationPct = 0.50; // 50% refund
  providerAction = 'Immediate review. Score heavily penalized. Risk of blacklist.';
  escalateHuman = true;
} else if (rating === 2) {
  severity = 'HIGH';
  compensationPct = 0.25; // 25% refund
  providerAction = 'Warning issued. Score penalized. Monitored for 30 days.';
  escalateHuman = false;
} else {
  severity = 'MEDIUM';
  compensationPct = 0;
  providerAction = 'Soft warning. Customer notified of improvement steps.';
  escalateHuman = false;
}

const estimatedRefund = Math.round((data.price_pkr || 0) * compensationPct);

// ── Provider Impact on WF2 Matching ──────────────────────
const matchingPenalty = severity === 'CRITICAL' ? -25
  : severity === 'HIGH' ? -15 : -5;

const resolution = {
  status: severity === 'CRITICAL' ? 'escalated_to_human' : 'dispute_resolved',
  dispute_type: 'quality_complaint',
  booking_id: data.booking_id,
  provider_name: data.provider_name,
  provider_id: data.provider_id,
  user_email: data.user_email,
  service_type: data.service_type,
  complaint_details: {
    rating_given: rating,
    review_text: review,
    sentiment: sentiment,
    auto_escalated_from_wf5: autoEscalated,
    severity: severity
  },
  decision: {
    compensation: {
      refund_percentage: compensationPct * 100,
      refund_pkr: estimatedRefund,
      eligible: estimatedRefund > 0,
      method: estimatedRefund > 0 ? 'Credit on next booking or cash' : 'No refund — medium severity only'
    },
    provider_penalty: {
      action: providerAction,
      matching_score_delta: matchingPenalty,
      flagged: true,
      under_review_days: severity === 'CRITICAL' ? 30 : 7
    },
    human_escalation: {
      required: escalateHuman,
      reason: escalateHuman ? 'CRITICAL rating — human agent must review within 24h' : null,
      ticket_id: escalateHuman ? `TKT-${Date.now()}` : null
    }
  },
  antigravity_trace: {
    reasoning: `Quality complaint for booking ${data.booking_id}. Rating: ${rating}/5. Severity: ${severity}. Compensation: PKR ${estimatedRefund} (${compensationPct * 100}%). Provider ${data.provider_name} score delta: ${matchingPenalty}. Human escalation: ${escalateHuman}.`,
    confidence: 88,
    decision_factors: ['rating_score', 'sentiment_analysis', 'review_keywords', 'auto_escalation_flag']
  },
  customer_message: estimatedRefund > 0
    ? `Aapki complaint receive ho gayi. Hum ne PKR ${estimatedRefund} refund approve kar diya hai. Aapki next booking mein credit mil jaega.`
    : `Aapki complaint record ho gayi. Hum ${data.provider_name} ki service improve karne ke liye kadam utha rahe hain.`,
  simulated_whatsapp:
    `Quality Complaint — Khadmat AI\n` +
    `Booking: ${data.booking_id}\n` +
    `Rating: ${rating}/5 (${severity})\n` +
    `${estimatedRefund > 0 ? `Refund approved: PKR ${estimatedRefund}` : 'No refund — complaint logged'}\n` +
    `${escalateHuman ? 'Human agent will contact you within 24h.' : 'Issue resolved automatically.'}`,
  workflow: 'WF6-QualityComplaint',
  timestamp: now.toISOString()
};

console.log('=== WF6 Quality Complaint ===');
console.log('Severity:', severity);
console.log('Refund:', estimatedRefund);
console.log('Human escalation:', escalateHuman);

return [{ json: resolution }];

// ============================================================
// WF6 — PRICE DISAGREEMENT HANDLER
// Customer was charged more than the quoted price.
// Compares quoted vs charged, decides refund amount.
// ============================================================
const data = $('WF6 — Router').first().json;
const now = new Date();

const quotedPrice = parseInt(data.quoted_price_pkr) || parseInt(data.price_pkr) || 0;
const chargedPrice = parseInt(data.charged_price_pkr) || parseInt(data.final_price_pkr) || 0;
const difference = chargedPrice - quotedPrice;
const overchargePercent = quotedPrice > 0 ? ((difference / quotedPrice) * 100).toFixed(1) : 0;

// ── Decision Logic ────────────────────────────────────────
let decision, refundAmount, providerNote;

if (difference <= 0) {
  decision = 'NO_OVERCHARGE';
  refundAmount = 0;
  providerNote = 'Charge matches or is below quote. No action needed.';
} else if (overchargePercent <= 10) {
  // Within 10% tolerance — minor variance, no refund but log it
  decision = 'MINOR_VARIANCE';
  refundAmount = 0;
  providerNote = `Overcharge within 10% tolerance (${overchargePercent}%). Logged as warning.`;
} else if (overchargePercent <= 30) {
  // Significant overcharge — partial refund of excess
  decision = 'PARTIAL_REFUND';
  refundAmount = Math.round(difference * 0.75); // refund 75% of excess
  providerNote = `Overcharge of ${overchargePercent}%. PKR ${refundAmount} refund issued. Strike added.`;
} else {
  // Major overcharge — full excess refunded
  decision = 'FULL_EXCESS_REFUND';
  refundAmount = difference;
  providerNote = `Major overcharge of ${overchargePercent}%. Full excess PKR ${refundAmount} refunded. Escalated for review.`;
}

const resolution = {
  status: 'dispute_resolved',
  dispute_type: 'price_disagreement',
  booking_id: data.booking_id,
  provider_name: data.provider_name,
  provider_id: data.provider_id,
  user_email: data.user_email,
  price_analysis: {
    quoted_pkr: quotedPrice,
    charged_pkr: chargedPrice,
    difference_pkr: difference,
    overcharge_percent: parseFloat(overchargePercent),
    decision: decision
  },
  resolution: {
    refund: {
      amount_pkr: refundAmount,
      eligible: refundAmount > 0,
      method: refundAmount > 0 ? 'Credit on next booking or cash refund' : 'No refund applicable'
    },
    provider_action: providerNote,
    flagged: difference > 0
  },
  antigravity_trace: {
    reasoning: `Price dispute for booking ${data.booking_id}. Quoted: PKR ${quotedPrice}. Charged: PKR ${chargedPrice}. Difference: PKR ${difference} (${overchargePercent}%). Decision: ${decision}. Refund: PKR ${refundAmount}.`,
    confidence: 97,
    decision_factors: ['quoted_price', 'charged_price', 'overcharge_percentage', 'tolerance_band']
  },
  customer_message: refundAmount > 0
    ? `Aapka case review hua. Quoted price PKR ${quotedPrice} tha lekin PKR ${chargedPrice} charge hua. PKR ${refundAmount} refund approve ho gaya.`
    : difference > 0
    ? `Farq PKR ${difference} hai jo 10% tolerance ke andar hai. Yeh acceptable variation hai — provider ko warning di gayi.`
    : 'Aapka charge quote ke mutabiq hai. Koi overcharge nahi hua.',
  simulated_whatsapp:
    `Price Dispute — Khadmat AI\n` +
    `Booking: ${data.booking_id}\n` +
    `Quoted: PKR ${quotedPrice} | Charged: PKR ${chargedPrice}\n` +
    `Decision: ${decision}\n` +
    `${refundAmount > 0 ? `Refund: PKR ${refundAmount}` : 'No refund applicable'}`,
  workflow: 'WF6-PriceDisagreement',
  timestamp: now.toISOString()
};

console.log('=== WF6 Price Disagreement ===');
console.log('Quoted:', quotedPrice, '| Charged:', chargedPrice, '| Diff:', difference);
console.log('Decision:', decision, '| Refund:', refundAmount);

return [{ json: resolution }];

// ============================================================
// WF6 — OVERRUN HANDLER
// Job took longer than expected, provider charging extra.
// Checks if customer was notified before overrun.
// Decides if extra charge is fair or should be disputed.
// ============================================================
const data = $('WF6 — Router').first().json;
const now = new Date();

const quotedPrice = parseInt(data.quoted_price_pkr) || parseInt(data.price_pkr) || 0;
const extraCharge = parseInt(data.extra_charge_pkr) || 0;
const customerNotified = data.customer_notified_before_overrun || false;
const customerApproved = data.customer_approved_overrun || false;
const estimatedDuration = parseInt(data.estimated_duration_mins) || 60;
const actualDuration = parseInt(data.actual_duration_mins) || 90;
const overrunMins = actualDuration - estimatedDuration;

// ── Decision Logic ────────────────────────────────────────
let decision, approvedExtra, note;

if (customerApproved) {
  decision = 'APPROVED_BY_CUSTOMER';
  approvedExtra = extraCharge;
  note = 'Customer pre-approved extra charge. No dispute.';
} else if (!customerNotified && extraCharge > 0) {
  decision = 'EXTRA_CHARGE_REJECTED';
  approvedExtra = 0;
  note = 'Customer was not notified before overrun. Extra charge rejected. Provider warned.';
} else if (overrunMins <= 15) {
  decision = 'MINOR_OVERRUN_ACCEPTED';
  approvedExtra = Math.min(extraCharge, Math.round(quotedPrice * 0.10));
  note = `Overrun under 15 mins — up to 10% extra (PKR ${approvedExtra}) accepted as fair.`;
} else {
  decision = 'OVERRUN_NEGOTIATED';
  approvedExtra = Math.round(extraCharge * 0.50);
  note = `Significant overrun (${overrunMins} mins). 50% of extra charge (PKR ${approvedExtra}) approved. Rest waived.`;
}

const resolution = {
  status: 'dispute_resolved',
  dispute_type: 'overrun',
  booking_id: data.booking_id,
  provider_name: data.provider_name,
  user_email: data.user_email,
  overrun_details: {
    estimated_duration_mins: estimatedDuration,
    actual_duration_mins: actualDuration,
    overrun_mins: overrunMins,
    quoted_price_pkr: quotedPrice,
    extra_charge_requested_pkr: extraCharge,
    customer_notified: customerNotified,
    customer_approved: customerApproved
  },
  resolution: {
    decision: decision,
    approved_extra_pkr: approvedExtra,
    total_fair_price_pkr: quotedPrice + approvedExtra,
    note: note
  },
  antigravity_trace: {
    reasoning: `Overrun dispute for booking ${data.booking_id}. Estimated: ${estimatedDuration}min, Actual: ${actualDuration}min (+${overrunMins}min). Extra requested: PKR ${extraCharge}. Customer notified: ${customerNotified}. Decision: ${decision}. Approved extra: PKR ${approvedExtra}.`,
    confidence: 91,
    decision_factors: ['customer_notification', 'customer_approval', 'overrun_duration', 'extra_charge_amount']
  },
  customer_message:
    `Job overrun dispute resolved.\n` +
    `Quoted: PKR ${quotedPrice} | Extra requested: PKR ${extraCharge}\n` +
    `Approved extra: PKR ${approvedExtra}\n` +
    `Total fair price: PKR ${quotedPrice + approvedExtra}`,
  simulated_whatsapp:
    `Overrun Dispute — Khadmat AI\n` +
    `Booking: ${data.booking_id}\n` +
    `Decision: ${decision}\n` +
    `Total fair charge: PKR ${quotedPrice + approvedExtra}`,
  workflow: 'WF6-Overrun',
  timestamp: now.toISOString()
};

console.log('=== WF6 Overrun ===');
console.log('Decision:', decision);
console.log('Approved extra:', approvedExtra);

return [{ json: resolution }];
